package com.harish.student_management.service; import com.harish.student_management.dto.*; import com.harish.student_management.entity.*; import com.harish.student_management.exception.ResourceNotFoundException; import com.harish.student_management.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor @Transactional public class TransportServiceImpl implements TransportService { private final StudentBusAllocationRepository allocations; private final StudentRepository students; private final BusRepository buses; private final BusRouteRepository routes; private final PickupPointRepository points;
 public TransportResponseDto allocate(TransportDtos.AllocationRequest r){Student s=students.findById(r.studentId).orElseThrow(()->new ResourceNotFoundException("Student not found"));Bus b=buses.findById(r.busId).orElseThrow(()->new ResourceNotFoundException("Bus not found"));BusRoute route=routes.findById(r.routeId).orElseThrow(()->new ResourceNotFoundException("Route not found"));PickupPoint p=points.findById(r.pickupPointId).orElseThrow(()->new ResourceNotFoundException("Pickup point not found"));PickupPoint d=points.findById(r.dropPointId).orElseThrow(()->new ResourceNotFoundException("Drop point not found"));if(route.getBus()!=null&&!route.getBus().getId().equals(b.getId()))throw new IllegalArgumentException("Bus is not assigned to selected route");if(!p.getRoute().getId().equals(route.getId())||!d.getRoute().getId().equals(route.getId()))throw new IllegalArgumentException("Points must belong to selected route");if(p.getId().equals(d.getId()))throw new IllegalArgumentException("Pickup and drop points must be different");String status=r.status==null?"ACTIVE":r.status.trim().toUpperCase();if("ACTIVE".equals(status)&&allocations.findByStudentId(s.getId()).stream().anyMatch(a->"ACTIVE".equalsIgnoreCase(a.getStatus())&&!a.getRoute().getId().equals(route.getId())))throw new IllegalArgumentException("Student already has an active allocation on another route");return map(allocations.save(StudentBusAllocation.builder().student(s).bus(b).route(route).pickupPoint(p).dropPoint(d).status(status).build()));} @Transactional(readOnly=true) public List<TransportResponseDto> byStudent(Long id){return allocations.findByStudentId(id).stream().map(this::map).toList();}@Transactional(readOnly=true) public List<TransportResponseDto> all(){return allocations.findAll().stream().map(this::map).toList();}private TransportResponseDto map(StudentBusAllocation a){return TransportResponseDto.builder().id(a.getId()).studentId(a.getStudent().getId()).studentName(a.getStudent().getName()).busId(a.getBus().getId()).busRegistration(a.getBus().getRegistrationNumber()).routeId(a.getRoute().getId()).routeName(a.getRoute().getName()).driverName(a.getRoute().getDriver()==null?null:a.getRoute().getDriver().getName()).pickupPointId(a.getPickupPoint().getId()).pickupPoint(a.getPickupPoint().getName()).dropPointId(a.getDropPoint().getId()).dropPoint(a.getDropPoint().getName()).status(a.getStatus()).build();}}
